  /** define det#fighters */
  function p_det_Num_fighters(t: T): void {
    t.switchCostume("1error");
    while (!!contains(t.costumeName(), "error")) {
      t.nextCostume();
    }
    t.switchCostume((t.costumeNumber() - 1));
    G.v.Num_offighters = t.costumeNumber();
  }

  /** define calibrate %s */
  function p_calibrate(t: T, a_1_2: Value): void {
    t.setSize(100);
    if (eq(a_1_2, "1")) {
      t.setXY(num(G.v._1x), num((num(G.v._1y) - 3)));
      if (eq(G.v.P1state, "Blowaway")) {
        t.setRotationStyle("all around");
        t.setDirection(num((num(G.v._1dir) * num((num(mathop("atan", num((num(G.v._1y_2) / num(G.v._1x_2))))) + 90)))));
      } else {
        t.setRotationStyle("left-right");
        t.setDirection(num(G.v._1dir));
      }
    } else {
      t.setXY(num(G.v._2x), num((num(G.v._2y) - 3)));
      if (eq(G.v.P2state, "Blowaway")) {
        t.setRotationStyle("all around");
        t.setDirection(num((num(G.v._2dir) * num((num(mathop("atan", num((num(G.v._2y_2) / num(G.v._2x_2))))) + 90)))));
      } else {
        t.setRotationStyle("left-right");
        t.setDirection(num(G.v._2dir));
      }
    }
    if (contains(t.costumeName(), "32`")) {
      t.setXY(t.x, t.y + 7);
    }
    if (contains(t.costumeName(), "]1`")) {
      t.setSize(90);
    }
    if (contains(G.v.invincible, a_1_2)) {
      t.setEffect("color", (num(mod(rt.timer(), 2)) * 200));
    }
  }

